<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Core/PublicPage.php';require dirname(__DIR__).'/app/Core/Database.php';
$rows=[];$error=null;$q=trim((string)($_GET['q']??''));$category=(string)($_GET['category']??'');
$labels=['TRANSPARENCY_SEAL'=>'Transparency Seal','BUDGET'=>'Budget','PROCUREMENT'=>'Procurement & Bidding','ANNUAL_REPORT'=>'Annual Reports','OPEN_DATA'=>'Open Data','LAW_OR_ISSUANCE'=>'Laws & Issuances','OTHER'=>'Other Public Record'];
try{$db=Database::connection();$sql="SELECT category,title,description,document_url,published_date FROM public_documents WHERE status='PUBLISHED'";$params=[];if(isset($labels[$category])){$sql.=' AND category=:category';$params['category']=$category;}if($q!==''){$sql.=' AND (title LIKE :q1 OR description LIKE :q2)';$params['q1']='%'.$q.'%';$params['q2']='%'.$q.'%';}$sql.=' ORDER BY published_date DESC,public_document_id DESC';$s=$db->prepare($sql);$s->execute($params);$rows=$s->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log('Transparency page: '.$e->getMessage());$error='Public records are temporarily unavailable.';}
pageHeader('Transparency & Open Data','Publicly released barangay transparency records and datasets.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">PUBLIC ACCOUNTABILITY</p><h1>Transparency &amp; Open Data</h1><p>Public documents and datasets released by Barangay San Antonio will be listed here after official review and publication.</p></div></section><section class="section"><div class="notice warning"><b>Publication status</b><p>This installation contains no verified official budget, procurement, annual report, or Transparency Seal documents yet. Do not treat sample content as an official disclosure. Authorized staff must publish verified records before they appear here.</p></div><form class="portal-form" method="get" action="<?= Security::e(url('transparency.php')) ?>"><div class="form-grid"><label>Search public records<input name="q" value="<?= Security::e($q) ?>" placeholder="Search title or description"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach($labels as $value=>$label): ?><option value="<?= Security::e($value) ?>" <?= $category===$value?'selected':'' ?>><?= Security::e($label) ?></option><?php endforeach; ?></select></label></div><button class="action-primary" type="submit">Search records</button></form><?php if($error): ?><div class="notice warning"><?= Security::e($error) ?></div><?php elseif(!$rows): ?><div class="publication-empty"><h2>No matching public documents</h2><p>When verified records are approved, they will appear here with their publication date and source link.</p></div><?php else: ?><div class="civic-grid"><?php foreach($rows as $r): ?><article class="civic-card"><span class="eyebrow"><?= Security::e($labels[$r['category']]??'Public Record') ?></span><h2><?= Security::e($r['title']) ?></h2><p><?= Security::e($r['description']??'') ?></p><p class="civic-meta">Published: <?= Security::e($r['published_date']??'Date not specified') ?></p><?php if(!empty($r['document_url'])): ?><a class="learn" href="<?= Security::e($r['document_url']) ?>" target="_blank" rel="noopener noreferrer">Open public record ↗</a><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section></main><?php pageFooter();
